  ObjectClassHandle server;
  REQUIRE_NOTHROW(server = owner->getObjectClassHandle(fixture_hla::fom::employee_server));
  std::wstring serverName;
  REQUIRE_NOTHROW(serverName = owner->getObjectClassName(server));
